$s=db()->prepare('SELECT * FROM support_threads WHERE id=? AND user_id=?');$s->execute([$tid,$uid]);$thread=$s->fetch();
$req=null;if($thread&&$thread['subscription_request_id']){$s=db()->prepare('SELECT * FROM subscription_requests WHERE id=?');$s->execute([$thread['subscription_request_id']]);$req=$s->fetch();}
